import {
  BackgroundContentCard,
  BackgroundContentCardProps,
} from "@/core/components/primitives/background-content-card/background-content-card";
import structure from "../../../styling/structure.module.less";
import styles from "./background-content-card-block.module.less";

export type BackgroundContentCardBlockProps = {
  title: string;
  cards: Array<BackgroundContentCardProps & { key: string }>;
};

export const BackgroundContentCardBlock = ({ title, cards }: BackgroundContentCardBlockProps) => {
  return (
    <div
      className={[
        structure.block,
        structure.blockPadded,
        structure.blockPaddedExceptOnLarge,
        structure.blockMaxWidthM,
        styles.main,
      ].join(" ")}
    >
      {title && <h1 className={styles.title}>{title}</h1>}

      <div className={styles.cards}>
        {cards?.map(({ key, ...props }) => <BackgroundContentCard key={key} {...props} />)}
      </div>
    </div>
  );
};
